package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

var (
	users  = make(map[string]User)
	mutex  sync.RWMutex
)

// GetAllUsers returns a list of all users
func GetAllUsers() []User {
	mutex.RLock()
	defer mutex.RUnlock()
	var list []User
	for _, u := range users {
		list = append(list, u)
	}
	return list
}

// CreateUser creates a new user
func CreateUser(u User) (User, error) {
	mutex.Lock()
	defer mutex.Unlock()

	u.ID = uuid.New().String()
	users[u.ID] = u
	return u, nil
}

// GetUserByID returns a user by ID
func GetUserByID(id string) (User, bool) {
	mutex.RLock()
	defer mutex.RUnlock()
	u, ok := users[id]
	return u, ok
}

package api

import (
	"encoding/json"
	"net/http"

	"rep-10/internal/service"
)

// GetUsersHandler handles GET requests for users
func GetUsersHandler(w http.ResponseWriter, r *http.Request) {
	list := service.GetAllUsers()
	json.NewEncoder(w).Encode(list)
}

// CreateUserHandler handles POST requests for users
func CreateUserHandler(w http.ResponseWriter, r *http.Request) {
	var u service.User
	if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	createdUser, err := service.CreateUser(u)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(createdUser)
}

// GetUserByIDHandler handles GET requests for a user by ID
func GetUserByIDHandler(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]
	u, ok := service.GetUserByID(id)
	if !ok {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(u)
}

package main

import (
	"log"
	"net/http"

	"rep-10/internal/api"
)

func main() {
	http.HandleFunc("/users", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			api.GetUsersHandler(w, r)
		case http.MethodPost:
			api.CreateUserHandler(w, r)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	})

	http.HandleFunc("/users/", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			api.GetUserByIDHandler(w, r)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	})

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package service_test

import (
	"testing"

	"rep-10/internal/service"
)

func TestCreateUser(t *testing.T) {
	u := service.User{Name: "Test User", Email: "test@example.com"}
	createdUser, err := service.CreateUser(u)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if createdUser.ID == "" {
		t.Error("expected user ID to be generated, got empty string")
	}
	if createdUser.Name != u.Name {
		t.Errorf("expected user name %q, got %q", u.Name, createdUser.Name)
	}
	if createdUser.Email != u.Email {
		t.Errorf("expected user email %q, got %q", u.Email, createdUser.Email)
	}
}

func TestGetAllUsers(t *testing.T) {
	// Clear existing users for a clean test environment
	service.ClearUsers()

	u1 := service.User{Name: "User 1", Email: "user1@example.com"}
	u2 := service.User{Name: "User 2", Email: "user2@example.com"}

	service.CreateUser(u1)
	service.CreateUser(u2)

	allUsers := service.GetAllUsers()
	if len(allUsers) != 2 {
		t.Errorf("expected 2 users, got %d", len(allUsers))
	}
}

func TestGetUserByID(t *testing.T) {
	// Clear existing users for a clean test environment
	service.ClearUsers()

	u := service.User{Name: "Find Me", Email: "findme@example.com"}
	createdUser, _ := service.CreateUser(u)

	foundUser, ok := service.GetUserByID(createdUser.ID)
	if !ok {
		t.Error("expected to find user, but got not found")
	}
	if foundUser.ID != createdUser.ID {
		t.Errorf("expected user ID %q, got %q", createdUser.ID, foundUser.ID)
	}

	_, ok = service.GetUserByID("nonexistent-id")
	if ok {
		t.Error("expected not to find user, but found one")
	}
}

